-- BrandShield schema (PostgreSQL). Generated by python -m scripts.export_schema; migrations in backend/alembic are the source of truth.

CREATE TABLE api_usage (
	id SERIAL NOT NULL, 
	provider VARCHAR(60) NOT NULL, 
	month VARCHAR(7) NOT NULL, 
	credits BIGINT NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_api_usage PRIMARY KEY (id), 
	CONSTRAINT uq_api_usage_provider UNIQUE (provider, month)
);


CREATE TABLE asset_verifications (
	id SERIAL NOT NULL, 
	brand_id INTEGER NOT NULL, 
	asset_type VARCHAR(12) NOT NULL, 
	asset_key VARCHAR(300) NOT NULL, 
	status VARCHAR(12) NOT NULL, 
	method VARCHAR(40), 
	note VARCHAR(300) NOT NULL, 
	verified_at TIMESTAMP WITH TIME ZONE, 
	verified_by_id INTEGER, 
	verified_by VARCHAR(120), 
	CONSTRAINT pk_asset_verifications PRIMARY KEY (id), 
	CONSTRAINT uq_asset_verifications_brand_id UNIQUE (brand_id, asset_type, asset_key), 
	CONSTRAINT fk_asset_verifications_brand_id_brands FOREIGN KEY(brand_id) REFERENCES brands (id) ON DELETE CASCADE
);

CREATE INDEX ix_asset_verifications_brand_id ON asset_verifications (brand_id);

CREATE TABLE audit_log (
	id SERIAL NOT NULL, 
	ts TIMESTAMP WITH TIME ZONE NOT NULL, 
	actor_id INTEGER, 
	actor VARCHAR(120) NOT NULL, 
	action VARCHAR(60) NOT NULL, 
	target VARCHAR(300) NOT NULL, 
	detail TEXT NOT NULL, 
	source VARCHAR(10) NOT NULL, 
	CONSTRAINT pk_audit_log PRIMARY KEY (id)
);

CREATE INDEX ix_audit_log_action ON audit_log (action);
CREATE INDEX ix_audit_log_ts ON audit_log (ts);

CREATE TABLE brand_logos (
	id SERIAL NOT NULL, 
	brand_id INTEGER NOT NULL, 
	label VARCHAR(120) NOT NULL, 
	path VARCHAR(300) NOT NULL, 
	format VARCHAR(10) NOT NULL, 
	width INTEGER NOT NULL, 
	height INTEGER NOT NULL, 
	size_bytes INTEGER NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_brand_logos PRIMARY KEY (id), 
	CONSTRAINT uq_brand_logos_brand_id UNIQUE (brand_id, sha256), 
	CONSTRAINT fk_brand_logos_brand_id_brands FOREIGN KEY(brand_id) REFERENCES brands (id) ON DELETE CASCADE
);

CREATE INDEX ix_brand_logos_brand_id ON brand_logos (brand_id);

CREATE TABLE brand_publishers (
	id SERIAL NOT NULL, 
	brand_id INTEGER NOT NULL, 
	store VARCHAR(20) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	publisher_id VARCHAR(120), 
	publisher_key VARCHAR(120) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_brand_publishers PRIMARY KEY (id), 
	CONSTRAINT uq_brand_publishers_brand_id UNIQUE (brand_id, store, publisher_key), 
	CONSTRAINT fk_brand_publishers_brand_id_brands FOREIGN KEY(brand_id) REFERENCES brands (id) ON DELETE CASCADE
);

CREATE INDEX ix_brand_publishers_brand_id ON brand_publishers (brand_id);

CREATE TABLE brands (
	id SERIAL NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	industry VARCHAR(120) NOT NULL, 
	aliases JSON NOT NULL, 
	keywords JSON NOT NULL, 
	domains JSON NOT NULL, 
	logo_path VARCHAR(300), 
	logo_format VARCHAR(10), 
	logo_width INTEGER, 
	logo_height INTEGER, 
	logo_size_bytes INTEGER, 
	logo_sha256 VARCHAR(64), 
	description TEXT, 
	archived_at TIMESTAMP WITH TIME ZONE, 
	source VARCHAR(10) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_brands PRIMARY KEY (id)
);


CREATE TABLE candidate_images (
	id SERIAL NOT NULL, 
	brand_id INTEGER NOT NULL, 
	purpose VARCHAR(20) NOT NULL, 
	path VARCHAR(300) NOT NULL, 
	format VARCHAR(10) NOT NULL, 
	width INTEGER NOT NULL, 
	height INTEGER NOT NULL, 
	size_bytes INTEGER NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	hashes JSON NOT NULL, 
	created_by INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_candidate_images PRIMARY KEY (id), 
	CONSTRAINT uq_candidate_images_brand_id UNIQUE (brand_id, sha256), 
	CONSTRAINT fk_candidate_images_brand_id_brands FOREIGN KEY(brand_id) REFERENCES brands (id) ON DELETE CASCADE
);

CREATE INDEX ix_candidate_images_brand_id ON candidate_images (brand_id);

CREATE TABLE collector_state (
	id SERIAL NOT NULL, 
	collector VARCHAR(40) NOT NULL, 
	status VARCHAR(15) NOT NULL, 
	reason VARCHAR(40), 
	message VARCHAR(400) NOT NULL, 
	latency_ms INTEGER, 
	last_attempt_at TIMESTAMP WITH TIME ZONE, 
	last_success_at TIMESTAMP WITH TIME ZONE, 
	consecutive_failures INTEGER NOT NULL, 
	next_retry_at TIMESTAMP WITH TIME ZONE, 
	cache_brand_id INTEGER, 
	cache JSON, 
	cached_at TIMESTAMP WITH TIME ZONE, 
	source VARCHAR(10) NOT NULL, 
	CONSTRAINT pk_collector_state PRIMARY KEY (id), 
	CONSTRAINT uq_collector_state_collector UNIQUE (collector)
);


CREATE TABLE detection_events (
	id SERIAL NOT NULL, 
	detection_id INTEGER NOT NULL, 
	at TIMESTAMP WITH TIME ZONE NOT NULL, 
	actor VARCHAR(120) NOT NULL, 
	actor_id INTEGER, 
	kind VARCHAR(20) NOT NULL, 
	from_status VARCHAR(20), 
	to_status VARCHAR(20), 
	note TEXT NOT NULL, 
	CONSTRAINT pk_detection_events PRIMARY KEY (id), 
	CONSTRAINT fk_detection_events_detection_id_detections FOREIGN KEY(detection_id) REFERENCES detections (id) ON DELETE CASCADE
);

CREATE INDEX ix_detection_events_detection_id ON detection_events (detection_id);

CREATE TABLE detections (
	id SERIAL NOT NULL, 
	brand_id INTEGER NOT NULL, 
	type VARCHAR(20) NOT NULL, 
	category VARCHAR(10) NOT NULL, 
	platform VARCHAR(20) NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	handle VARCHAR(200), 
	package_id VARCHAR(200), 
	publisher VARCHAR(200), 
	profile_url VARCHAR(500), 
	score INTEGER NOT NULL, 
	band VARCHAR(10) NOT NULL, 
	severity VARCHAR(10) DEFAULT 'LOW' NOT NULL, 
	algorithm_version VARCHAR(10), 
	scored_at TIMESTAMP WITH TIME ZONE, 
	status VARCHAR(20) NOT NULL, 
	resolution VARCHAR(20), 
	canonical_key VARCHAR(400) NOT NULL, 
	first_seen_at TIMESTAMP WITH TIME ZONE, 
	last_seen_at TIMESTAMP WITH TIME ZONE, 
	last_scan_id INTEGER, 
	score_history JSON NOT NULL, 
	notes JSON NOT NULL, 
	reasons JSON NOT NULL, 
	evidence JSON NOT NULL, 
	details JSON NOT NULL, 
	stale BOOLEAN NOT NULL, 
	source VARCHAR(10) NOT NULL, 
	origin VARCHAR(12) DEFAULT 'scan' NOT NULL, 
	found_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_detections PRIMARY KEY (id), 
	CONSTRAINT uq_detections_brand_id UNIQUE (brand_id, canonical_key), 
	CONSTRAINT fk_detections_brand_id_brands FOREIGN KEY(brand_id) REFERENCES brands (id) ON DELETE CASCADE, 
	CONSTRAINT fk_detections_last_scan_id_scans FOREIGN KEY(last_scan_id) REFERENCES scans (id) ON DELETE SET NULL
);

CREATE INDEX ix_detections_brand_id ON detections (brand_id);
CREATE INDEX ix_detections_platform ON detections (platform);
CREATE INDEX ix_detections_status ON detections (status);

CREATE TABLE lookalike_cases (
	id SERIAL NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	expected VARCHAR(15) NOT NULL, 
	builtin BOOLEAN NOT NULL, 
	source VARCHAR(10) NOT NULL, 
	created_by INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_lookalike_cases PRIMARY KEY (id), 
	CONSTRAINT fk_lookalike_cases_created_by_users FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL
);

CREATE UNIQUE INDEX uq_lookalike_cases_builtin_name ON lookalike_cases (name) WHERE builtin;

CREATE TABLE official_accounts (
	id SERIAL NOT NULL, 
	brand_id INTEGER NOT NULL, 
	platform VARCHAR(20) NOT NULL, 
	handle VARCHAR(100) NOT NULL, 
	handle_key VARCHAR(100) NOT NULL, 
	url VARCHAR(300) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	check_message VARCHAR(300), 
	last_checked_at TIMESTAMP WITH TIME ZONE, 
	source VARCHAR(10) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_official_accounts PRIMARY KEY (id), 
	CONSTRAINT uq_official_accounts_brand_id UNIQUE (brand_id, platform, handle_key), 
	CONSTRAINT fk_official_accounts_brand_id_brands FOREIGN KEY(brand_id) REFERENCES brands (id) ON DELETE CASCADE
);

CREATE INDEX ix_official_accounts_brand_id ON official_accounts (brand_id);

CREATE TABLE official_apps (
	id SERIAL NOT NULL, 
	brand_id INTEGER NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	package_id VARCHAR(155) NOT NULL, 
	package_key VARCHAR(155) NOT NULL, 
	publisher VARCHAR(120) NOT NULL, 
	store_id VARCHAR(20), 
	stores JSON NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	source VARCHAR(10) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_official_apps PRIMARY KEY (id), 
	CONSTRAINT uq_official_apps_brand_id UNIQUE (brand_id, package_key), 
	CONSTRAINT fk_official_apps_brand_id_brands FOREIGN KEY(brand_id) REFERENCES brands (id) ON DELETE CASCADE
);

CREATE INDEX ix_official_apps_brand_id ON official_apps (brand_id);

CREATE TABLE official_matches (
	id SERIAL NOT NULL, 
	brand_id INTEGER NOT NULL, 
	scan_id INTEGER, 
	kind VARCHAR(10) NOT NULL, 
	platform VARCHAR(20), 
	label VARCHAR(300) NOT NULL, 
	reason VARCHAR(40) NOT NULL, 
	matched_rule VARCHAR(300) NOT NULL, 
	match_key VARCHAR(400) NOT NULL, 
	url VARCHAR(500), 
	last_seen_at TIMESTAMP WITH TIME ZONE, 
	times_seen INTEGER NOT NULL, 
	official_account_id INTEGER, 
	official_app_id INTEGER, 
	source VARCHAR(10) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_official_matches PRIMARY KEY (id), 
	CONSTRAINT uq_official_matches_brand_id UNIQUE (brand_id, match_key), 
	CONSTRAINT fk_official_matches_brand_id_brands FOREIGN KEY(brand_id) REFERENCES brands (id) ON DELETE CASCADE, 
	CONSTRAINT fk_official_matches_scan_id_scans FOREIGN KEY(scan_id) REFERENCES scans (id) ON DELETE SET NULL, 
	CONSTRAINT fk_official_matches_official_account_id_official_accounts FOREIGN KEY(official_account_id) REFERENCES official_accounts (id) ON DELETE SET NULL, 
	CONSTRAINT fk_official_matches_official_app_id_official_apps FOREIGN KEY(official_app_id) REFERENCES official_apps (id) ON DELETE SET NULL
);

CREATE INDEX ix_official_matches_brand_id ON official_matches (brand_id);

CREATE TABLE refresh_tokens (
	id SERIAL NOT NULL, 
	jti VARCHAR(64) NOT NULL, 
	user_id INTEGER NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	revoked_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_refresh_tokens PRIMARY KEY (id), 
	CONSTRAINT fk_refresh_tokens_user_id_users FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX ix_refresh_tokens_jti ON refresh_tokens (jti);
CREATE INDEX ix_refresh_tokens_user_id ON refresh_tokens (user_id);

CREATE TABLE reports (
	id SERIAL NOT NULL, 
	brand_id INTEGER NOT NULL, 
	filename VARCHAR(200) NOT NULL, 
	format VARCHAR(5) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	status VARCHAR(10) NOT NULL, 
	detection_ids JSON NOT NULL, 
	snapshot JSON NOT NULL, 
	approved_by INTEGER, 
	approved_at TIMESTAMP WITH TIME ZONE, 
	size_bytes INTEGER NOT NULL, 
	params JSON NOT NULL, 
	file_path VARCHAR(300), 
	includes_sample BOOLEAN NOT NULL, 
	source VARCHAR(10) NOT NULL, 
	created_by INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_reports PRIMARY KEY (id), 
	CONSTRAINT fk_reports_brand_id_brands FOREIGN KEY(brand_id) REFERENCES brands (id) ON DELETE CASCADE, 
	CONSTRAINT fk_reports_approved_by_users FOREIGN KEY(approved_by) REFERENCES users (id) ON DELETE SET NULL, 
	CONSTRAINT fk_reports_created_by_users FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_reports_brand_id ON reports (brand_id);

CREATE TABLE scans (
	id SERIAL NOT NULL, 
	job_id VARCHAR(40) NOT NULL, 
	brand_id INTEGER NOT NULL, 
	scope VARCHAR(10) NOT NULL, 
	state VARCHAR(10) NOT NULL, 
	progress INTEGER NOT NULL, 
	message VARCHAR(300) NOT NULL, 
	steps JSON NOT NULL, 
	result JSON, 
	data_mode VARCHAR(10) NOT NULL, 
	created_by INTEGER, 
	started_by VARCHAR(120) NOT NULL, 
	counts JSON NOT NULL, 
	source_report JSON NOT NULL, 
	timings JSON NOT NULL, 
	errors JSON NOT NULL, 
	started_at TIMESTAMP WITH TIME ZONE, 
	finished_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_scans PRIMARY KEY (id), 
	CONSTRAINT uq_scans_job_id UNIQUE (job_id), 
	CONSTRAINT fk_scans_brand_id_brands FOREIGN KEY(brand_id) REFERENCES brands (id) ON DELETE CASCADE, 
	CONSTRAINT fk_scans_created_by_users FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_scans_brand_id ON scans (brand_id);
CREATE UNIQUE INDEX uq_scans_one_active_per_brand ON scans (brand_id) WHERE state IN ('queued', 'running');

CREATE TABLE settings (
	id SERIAL NOT NULL, 
	key VARCHAR(80) NOT NULL, 
	value JSON, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_by INTEGER, 
	CONSTRAINT pk_settings PRIMARY KEY (id), 
	CONSTRAINT uq_settings_key UNIQUE (key), 
	CONSTRAINT fk_settings_updated_by_users FOREIGN KEY(updated_by) REFERENCES users (id) ON DELETE SET NULL
);


CREATE TABLE sources (
	id SERIAL NOT NULL, 
	platform VARCHAR(20) NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	kind VARCHAR(10) NOT NULL, 
	description VARCHAR(200) NOT NULL, 
	status VARCHAR(15) NOT NULL, 
	monitored BOOLEAN NOT NULL, 
	message VARCHAR(300) NOT NULL, 
	detail VARCHAR(200) NOT NULL, 
	last_sync TIMESTAMP WITH TIME ZONE, 
	retry_in_minutes INTEGER, 
	stale_since TIMESTAMP WITH TIME ZONE, 
	source VARCHAR(10) NOT NULL, 
	CONSTRAINT pk_sources PRIMARY KEY (id), 
	CONSTRAINT uq_sources_platform UNIQUE (platform)
);


CREATE TABLE stored_files (
	path VARCHAR(300) NOT NULL, 
	content BYTEA NOT NULL, 
	content_type VARCHAR(100) NOT NULL, 
	size_bytes INTEGER NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_stored_files PRIMARY KEY (path)
);


CREATE TABLE text_analysis_cache (
	key VARCHAR(64) NOT NULL, 
	provider VARCHAR(20) NOT NULL, 
	value JSON NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_text_analysis_cache PRIMARY KEY (key)
);


CREATE TABLE users (
	id SERIAL NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	email VARCHAR(254) NOT NULL, 
	password_hash VARCHAR(100) NOT NULL, 
	role VARCHAR(20) NOT NULL, 
	active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_users PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_users_email ON users (email);
